/**
 * Drawing a QR code onto a `<canvas>`.
 *
 * `qrcode-generator` computes the module matrix and stops there. It ships
 * renderers (`renderTo2dContext`, `createSvgTag`, ...) but they hard-code black
 * on white and offer no quiet zone, so the component would still have to draw
 * the thing itself -- hence this module rather than a direct call from
 * `ld-quiz.js`.
 *
 * The option names mirror the widely used `qrcode` npm package, because that is
 * the vocabulary the call site was already written in and the one anybody
 * reading it will expect.
 */

import qrcode from "qrcode-generator";

/** Error-correction levels as the `qrcode` package numbers them. */
const LEVEL_BY_NUMBER = { 0: "L", 1: "M", 2: "Q", 3: "H" };

/**
 * Draw `text` as a QR code, sizing `canvas` to fit.
 *
 * @param {HTMLCanvasElement} canvas Resized to the computed symbol size.
 * @param {string} text The payload -- for this component, the join URL.
 * @param {object} [options]
 * @param {number} [options.width=0] Size budget in pixels; see below.
 * @param {number} [options.margin=4] Quiet zone in modules.
 * @param {string|number} [options.errorCorrectionLevel="Q"] 'L'|'M'|'Q'|'H'.
 * @param {number} [options.typeNumber] Pin a symbol version instead of auto.
 * @param {string} [options.colorDark="#000000"]
 * @param {string} [options.colorLight="#ffffff"]
 */
export function toCanvas(canvas, text, options = {}) {
  const level = options.errorCorrectionLevel || "Q";
  const errorCorrectionLevel =
    typeof level === "number" ? LEVEL_BY_NUMBER[level] || "Q" : level;

  // Version 0 means "smallest symbol that holds the data". Nothing here pins a
  // version: the join URL changes length with the room id, so a fixed version
  // would either waste modules or start rejecting URLs.
  const qr = qrcode(options.typeNumber || 0, errorCorrectionLevel);
  qr.addData(text);
  qr.make();
  const moduleCount = qr.getModuleCount();

  // The quiet zone is not padding. A scanner finds the symbol by locating the
  // three finder patterns against unbroken light background, and the spec asks
  // for four clear modules on every side. Drawn flush to the canvas edge the
  // code stops being readable the moment the slide behind it is not white.
  const marginModules = typeof options.margin === "number" ? options.margin : 4;

  // `width` is a budget, not the final size. Modules have to land on whole
  // pixels -- a fractional module size leaves the browser antialiasing every
  // edge, which is exactly the contrast a scanner needs -- so the module size is
  // floored and the canvas comes out at or below the requested width.
  const moduleSize = options.width
    ? Math.floor(options.width / (moduleCount + 2 * marginModules))
    : 4;
  const size = moduleSize * moduleCount + 2 * moduleSize * marginModules;

  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d");

  // Painting the light colour across the whole canvas, quiet zone included: a
  // transparent canvas would let the host page show through and the quiet zone
  // would only exist in theory.
  ctx.fillStyle = options.colorLight || "#ffffff";
  ctx.fillRect(0, 0, size, size);

  ctx.fillStyle = options.colorDark || "#000000";
  const offset = moduleSize * marginModules;
  for (let row = 0; row < moduleCount; row++) {
    for (let col = 0; col < moduleCount; col++) {
      if (qr.isDark(row, col)) {
        ctx.fillRect(
          offset + col * moduleSize,
          offset + row * moduleSize,
          moduleSize,
          moduleSize,
        );
      }
    }
  }
}
